void llm_graph_input_dsv4::set_input(const llama_ubatch * ubatch) {
    const int64_t n_stream = cparams.kv_unified ? 1 : ubatch->n_seqs_unq;

    GGML_ASSERT(ubatch->n_tokens % n_stream == 0);

    const auto plan = mctx->get_comp_plan(ubatch);

    dsv4_set_comp_inputs(comp, plan, "comp", debug, ubatch->n_tokens, n_stream);

    if (raw) {
        const auto raw_plan = mctx->get_raw_plan(ubatch);

        dsv4_set_i32(raw->k_idxs, raw_plan.k_idxs);
        dsv4_set_i32(raw->v_idxs, raw_plan.v_idxs);
        dsv4_set_kq_mask(raw->kq_mask, raw_plan, ubatch->n_tokens, n_stream);
    }
}

bool llm_graph_input_dsv4::can_reuse(const llm_graph_params & params) {
    mctx = static_cast<const llama_kv_cache_dsv4_context *>(params.mctx);

    bool res = true;

    res &= comp.state_pos->ne[0] == params.ubatch.n_tokens;
    res &= comp.state_persist_src_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_persist_src_idxs.size();
    res &= comp.state_persist_dst_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_persist_dst_idxs.size();
    res &= comp.state_restore_src_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_restore_src_idxs.size();
    res &= comp.state_restore_dst_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_restore_dst_idxs.size();
    res &= comp.state_snapshot_src_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_snapshot_src_idxs.size();
    res &= comp.state_snapshot_dst_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_snapshot_dst_idxs.size();
    res &= comp.state_read_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_read_idxs.size();
    res &= comp.state_write_idxs->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_write_idxs.size();
    res &= comp.state_write_pos->ne[0] == (int64_t) mctx->get_comp_plan(&params.ubatch).state_write_pos.size();

    if (raw) {
        const auto raw_plan = mctx->get_raw_plan(&params.ubatch);

        res &= raw->k_idxs->ne[0] == (int64_t) raw_plan.k_idxs.size();
        res &= raw->v_idxs->ne[0] == (int64_t) raw_plan.v_idxs.size();
        res &= dsv4_can_reuse_raw_kq_mask(raw->kq_mask, mctx->get_raw(), params.ubatch, params.cparams.kv_unified ? 1 : params.ubatch.n_seqs_unq);
    }

    return res;
}

